function quick(p,i,title,desc){return `<button class="quick" data-go="${p}">${icon(i)}<span><strong>${esc(title)}</strong><small>${esc(desc)}</small></span></button>`;}
let taps=[];$('#brand-logo').onclick=()=>{const now=Date.now();taps=taps.filter(t=>now-t<1800);taps.push(now);if(taps.length>=3){taps=[];admin?go('admin'):adminLogin();}};
$('#theme').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('sap.v3.theme',document.body.classList.contains('dark')?'dark':'light');};if(localStorage.getItem('sap.v3.theme')==='dark')document.body.classList.add('dark');$('#refresh').onclick=()=>sync();
function title(a,b,c){$('#page-title').textContent=a;$('#page-title').hidden=!a;$('#page-description').textContent=b;$('#page-description').hidden=!b;$('#section-tag').textContent=c||'SAP-TEMIN · '+f.session;}
function pbdOnly(){return selectedAssessments().length>0&&selectedAssessments().every(id=>id==='PBD_MID'||id==='PBD_END')||Boolean(f.year&&Number(f.year)<=3&&selectedAssessments().includes('COMBINED'));}
function render(){const group=page==='dialog'?'reports':page;$('#filters-box').hidden=['admin','settings','help','placement'].includes(page);$('#sort-field').hidden=!['students','reports'].includes(page);document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===group));people=viewData(state.records,f);currentSubjects=[...new Set(people.flatMap(p=>(p.assessmentViews||[p]).flatMap(v=>[...Object.keys(v.marks),...Object.keys(v.pbd)])))].filter(s=>!f.subject||s===f.subject).sort((a,b)=>Object.keys(SUBJECTS).indexOf(a)-Object.keys(SUBJECTS).indexOf(b));$('#scope-label').textContent=[f.session,f.year?'Tahun '+f.year:'Semua tahun',f.className||'Semua kelas',assessmentName(),...(f.subject?[f.subject]:[])].join(' · ');const views={home:homeView,analysis:analysisView,students:studentsView,intervention:interventionView,reports:reportsView,dialog:dialogView,settings:settingsView,help:helpView,admin:adminView,placement:placementView};(views[page]||homeView)();}
function printTitle(){return `<div class="print-title"><h2>SAP-TEMIN · SK TEMIN</h2><p>${esc($('#scope-label').textContent)}</p></div>`;}
function assessmentLabel(id){return id==='COMBINED'?'UASA + MPT4 · bersama PBD Akhir':state.config.assessments.find(a=>a.id===id)?.name||id;}
function selectedAssessments(){return f.assessments||[f.assessment];}
function assessmentName(){return selectedAssessments().map(assessmentLabel).join(' + ')||'Tiada pentaksiran dipilih';}
function renderAssessmentPicker(){const ids=selectedAssessments();$('#assessment-summary').textContent=assessmentName();$('#f-assessment').innerHTML=[{id:'COMBINED'},...state.config.assessments].map(a=>`<label><input type="checkbox" value="${esc(a.id)}" ${ids.includes(a.id)?'checked':''}><span>${esc(assessmentLabel(a.id))}</span></label>`).join('');}
// Close the assessment menu on outside mouse/touch input or Escape.
document.addEventListener('pointerdown',e=>{const picker=$('#assessment-picker');if(picker.open&&!picker.contains(e.target))picker.open=false;});
document.addEventListener('keydown',e=>{const picker=$('#assessment-picker');if(e.key==='Escape'&&picker.open){picker.open=false;picker.querySelector('summary').focus();}});
$('#f-assessment').onchange=e=>{const id=e.target.value;let ids=selectedAssessments().filter(x=>x!==id);if(e.target.checked){if(id==='COMBINED')ids=ids.filter(x=>!['UASA','MPT4','PBD_END'].includes(x));else if(['UASA','MPT4','PBD_END'].includes(id))ids=ids.filter(x=>x!=='COMBINED');ids.push(id);}f.assessments=ids;f.assessment=ids.length===1?ids[0]:'MULTI';renderAssessmentPicker();rebuildFilters();render();};
function metrics(){const m=dashboardStats(people,f.subject,outcomeThreshold);return {...m,focus:m.pbdLow.length};}
function tabs(items,current,attr){return `<div class="view-tabs screen-only" role="tablist">${items.map(([id,label,disabled=false])=>`<button type="button" ${disabled?'disabled aria-disabled="true"':''} role="tab" aria-selected="${id===current}" class="${id===current?'active':''}" data-${attr}="${id}">${label}</button>`).join('')}</div>`;}
function infoButton(topic){return `<button class="info-btn screen-only" data-info="${topic}" aria-label="Penerangan ${topic}">i</button>`;}
function hasPbdData(){return people.some(p=>chartPbdRecords(p,f.subject).length);}
function hasMarkData(){return people.some(p=>Object.keys(p.marks).some(s=>!f.subject||s===f.subject));}
function chooseDataTab(current){return current==='pbd'&&!hasPbdData()&&hasMarkData()?'marks':current==='marks'&&!hasMarkData()&&hasPbdData()?'pbd':current;}
function emptyData(message){return `<div class="empty compact-empty"><h3>${message}</h3><p>Pilih pentaksiran atau skop lain melalui Penapis.</p></div>`;}
function statCard(label,value,note,action='',tone=''){return `<${action?'button type="button"':'article'} class="kpi stat-card ${tone}" ${action?`data-stat="${action}"`:''}><span>${label}</span><strong>${value}</strong><small>${note}</small></${action?'button':'article'}>`;}
function kpi(label,value,note,green=false){return `<article class="kpi ${green?'green':''}"><span>${label}</span><strong>${value}</strong><small>${note}</small></article>`;}
function homeView(){
 title('Ringkasan sekolah','','UTAMA');dashboardMode=chooseDataTab(dashboardMode);const m=metrics(),pbd=dashboardMode==='pbd';
 const cards=pbd?`${statCard('Murid',people.length,'Dalam skop semasa')}${statCard('Penguasaan TP3–TP6',m.mastery===null?'—':m.mastery.toFixed(1)+'%','Daripada rekod TP sah','','green')}${statCard('Perlu bimbingan',m.pbdLow.length,'Mempunyai TP1 / TP2','pbd-low','attention')}${statCard('Tiada TP sah',people.length-m.pbdAssessed.length,'Dalam pentaksiran dipilih','pbd-missing')}`:`${statCard('Murid',people.length,'Dalam skop semasa')}${statCard('Purata markah',m.avg===null?'—':m.avg.toFixed(1)+'%','Daripada markah sah','','green')}${statCard('Bawah '+outcomeThreshold+' markah',m.markLow.length,'Sekurang-kurangnya satu subjek','exam-low','attention')}${statCard('Belum lengkap',m.markUnknown.length,'Ada T / TD atau tiada markah','exam-unknown')}`;
 $('#view').innerHTML=`${printTitle()}${tabs([['pbd','PBD',!hasPbdData()],['marks','Peperiksaan',!hasMarkData()]],dashboardMode,'dashboard-mode')}<div class="kpi-grid dashboard-kpis">${cards}</div>${pbd?`<section class="panel"><div class="panel-head"><h3>Penguasaan PBD</h3>${infoButton('tp')}</div>${hasPbdData()?tpBars():emptyData('Belum ada data PBD dalam pilihan ini.')}</section>`:`${hasMarkData()?outcomesChart():`<section class="panel">${emptyData('Belum ada markah dalam pilihan ini.')}</section>`}<details class="panel disclosure"><summary>Purata markah mengikut subjek</summary><div class="disclosure-body">${subjectBars(m.marks)}</div></details>`}${state.demo?`<div class="notice warn">${state.preview?'Pratonton peranti · belum disimpan ke Google Sheets.':'Data contoh rekaan.'}</div>`:''}`;
 bindOutcomeThreshold();
}
function tpBars(){
 const eligible=people.filter(p=>chartPbdRecords(p,f.subject).length).length;
 return [1,2,3,4,5,6].map(n=>{const tp='TP'+n,count=tpMembers(people,tp,f.subject).length,percent=eligible?count/eligible*100:0;return `<button type="button" class="chart-bar tp-chart-bar" data-tp="${tp}" aria-label="${tp}: ${count} murid. Buka senarai murid."><strong>${tp}</strong><span class="bar-track"><span class="bar-fill tp-color-${n}" style="width:${percent}%"></span></span><span class="chart-count">${count} murid <small>${percent.toFixed(0)}%</small></span></button>`;}).join('');
}
function subjectBars(rows){const subs=[...new Set(rows.map(r=>r.subject))];return subs.map(s=>{const v=rows.filter(r=>r.subject===s);const avg=v.reduce((a,r)=>a+r.mark,0)/v.length;return `<div class="bar-row"><button data-subject="${esc(s)}">${esc(s)}</button><div class="bar-track"><div class="bar-fill" style="width:${avg}%"></div></div><small>${avg.toFixed(1)}%</small></div>`;}).join('')||'<p class="hint">Tiada markah dalam pilihan ini.</p>';}
let outcomeThreshold=35;
function outcomesChart(){
 const subs=currentSubjects.filter(s=>people.some(p=>p.marks[s]));
 if(!subs.length)return '';
 return `<section class="panel outcomes-panel"><div class="panel-head"><div><h3>Pencapaian subjek</h3><p>Klik palang untuk senarai murid.</p></div><label>Ambang markah<select id="outcome-threshold">${[20,35,50].map(n=>option(n,n+' markah',outcomeThreshold)).join('')}</select></label></div><div class="chart-legend"><span><i class="legend-dot low"></i>Bawah ${outcomeThreshold} markah</span><span><i class="legend-dot met"></i>${outcomeThreshold} markah ke atas</span><span><i class="legend-dot unknown"></i>T / TD / belum ditaksir</span></div>${subs.map(s=>{
 const low=outcomeMembers(people,s,'low',outcomeThreshold).length,met=outcomeMembers(people,s,'met',outcomeThreshold).length,unknown=outcomeMembers(people,s,'unknown',outcomeThreshold).length,total=low+met+unknown;
 return `<div class="outcome-row"><strong title="${esc(SUBJECTS[s]||s)}">${esc(s)}</strong><div class="outcome-stack" aria-label="${esc(s)}: ${low} bawah ambang, ${met} mencapai ambang, ${unknown} belum ditaksir">${[['low',low],['met',met],['unknown',unknown]].filter(([,n])=>n).map(([kind,n])=>`<button type="button" class="outcome-segment ${kind}" data-outcome="${kind}" data-chart-subject="${esc(s)}" style="flex:${n}" aria-label="${esc(s)}: ${n} murid ${kind==='low'?'bawah '+outcomeThreshold:kind==='met'?'sekurang-kurangnya '+outcomeThreshold:'belum ditaksir'}">${n}</button>`).join('')}</div><button class="outcome-count" data-outcome="low" data-chart-subject="${esc(s)}">${low} / ${total}<small>bawah ambang</small></button></div>`;
 }).join('')}<div class="chart-footnote">${infoButton('markah')}</div></section>`;
}
function bindOutcomeThreshold(){const el=$('#outcome-threshold');if(el)el.onchange=e=>{outcomeThreshold=Number(e.target.value);homeView();};}
function showChartMembers(title,ps,details){modal(title,`<p class="hint">${ps.length} murid · ${esc($('#scope-label').textContent)}${f.subject?' · '+esc(SUBJECTS[f.subject]||f.subject):''}</p>${ps.slice().sort((a,b)=>a.year-b.year||a.className.localeCompare(b.className)||a.name.localeCompare(b.name,'ms')).map(p=>`<div class="list-item"><button class="text-btn" data-profile="${esc(p.key)}">${esc(p.name)}</button><p>${p.year} ${esc(p.className)}</p><small>${details(p)}</small></div>`).join('')||'<p>Tiada murid dalam pilihan ini.</p>'}`);}
function toolbar(){return `<div class="table-meta"><span class="badge">${people.length} murid</span>${infoButton('ranking')}</div>`;}
function resultsTable(list=people){if(list.some(p=>p.assessmentViews))return multiResultsTable(list);if(!list.length)return '<div class="empty"><h2>Tiada keputusan dalam pilihan ini.</h2><p>Tukar sesi, pentaksiran atau penapis.</p></div>';return `<div class="table-scroll"><table class="results-table"><thead><tr><th class="rank">${f.sort==='subject'?'Kedudukan subjek':'Kedudukan'}</th><th class="name">Nama murid / Kelas</th><th>Pentaksiran</th>${currentSubjects.map(s=>`<th title="${esc(SUBJECTS[s]||s)}">${esc(s)}</th>`).join('')}<th>Bil. A</th><th>Jumlah</th><th>Purata</th></tr></thead>${list.map(p=>{const hasMarks=Object.keys(p.marks).length;const hasPbd=Object.keys(p.pbd).length;const name=`<td class="name" ${hasMarks&&hasPbd?'rowspan="2"':''}><button data-profile="${esc(p.key)}">${esc(p.name)}</button><small>${p.year} ${esc(p.className)}</small>${hasMarks&&!p.complete?'<span class="badge warn">Belum lengkap</span>':''}</td>`;const rank=`<td class="rank" ${hasMarks&&hasPbd?'rowspan="2"':''}>${hasMarks?((f.sort==='subject'?p.subjectRank:p.rank)||'—'):'—'}</td>`;let html='';if(hasMarks)html=`<tr class="uasa-row">${rank}${name}<td>${f.assessment==='COMBINED'?(p.year===4?'UASA + MPT4':'UASA'):esc(assessmentLabel(f.assessment))}</td>${currentSubjects.map(s=>{const r=p.marks[s];return `<td title="${esc(r?.source||'')}">${r?.status==='OK'?`<span class="mark">${r.mark}</span> <span class="badge grade-badge grade-${esc(r.grade)}">${esc(r.grade)}</span>`:esc(r?.status||'—')}</td>`;}).join('')}<td><strong>${p.aCount}</strong></td><td><strong>${p.total}/${Object.keys(p.marks).length*100}</strong></td><td>${p.average===null?'—':p.average.toFixed(2)+'%'}</td></tr>`;if(hasPbd)html+=`<tr class="pbd-row">${hasMarks?'':rank+name}<td>${f.assessment==='COMBINED'?'PBD Akhir':esc(assessmentLabel(f.assessment))}</td>${currentSubjects.map(s=>`<td>${p.pbd[s]?`<span class="tp ${/^TP[12]$/.test(p.pbd[s].tp)?'low':''}">${esc(p.pbd[s].tp||p.pbd[s].status)}</span>`:'—'}</td>`).join('')}<td colspan="3">Penguasaan PBD</td></tr>`;return `<tbody class="student-result">${html}</tbody>`;}).join('')}</table></div>`;}
function multiResultsTable(list){
 const onlyPbd=list.every(p=>!Object.keys(p.marks).length);
 const chosen=selectedAssessments();const oldMode=f.assessment;
 const groups=list.map(p=>{
  let rows=[];
  for(const v of p.assessmentViews||[]){f.assessment=v.id;const html=resultsTable([{...v,assessmentViews:undefined}]);const body=html.match(/<tbody class="student-result">([\s\S]*?)<\/tbody>/)?.[1]||'';rows.push(...body.matchAll(/<tr[^>]*>[\s\S]*?<\/tr>/g));}
  const mid=p.assessmentViews?.find(v=>v.id==='PBD_MID');const end=p.assessmentViews?.find(v=>v.id==='PBD_END'||v.id==='COMBINED');
  const compare=chosen.includes('PBD_MID')&&(chosen.includes('PBD_END')||chosen.includes('COMBINED'));
  const count=rows.length+(compare?1:0);
  let body=rows.map((m,i)=>{let row=m[0].replace(/<td class="(?:rank|name)"[\s\S]*?<\/td>/g,'');if(i===0)row=row.replace(/(<tr[^>]*>)/,`$1<td class="rank" rowspan="${count}">${(f.sort==='subject'?p.subjectRank:p.rank)||'—'}</td><td class="name" rowspan="${count}"><button data-profile="${esc(p.key)}">${esc(p.name)}</button><small>${p.year} ${esc(p.className)}</small></td>`);return row;}).join('');
  if(compare)body+=`<tr class="progress-row"><td>Perubahan TP</td>${currentSubjects.map(sub=>{const a=mid?.pbd[sub]?.tp,b=end?.pbd[sub]?.tp;if(!/^TP[1-6]$/.test(a||'')||!/^TP[1-6]$/.test(b||''))return '<td>—</td>';const d=Number(b.slice(2))-Number(a.slice(2));return `<td class="${d>0?'progress-up':d<0?'progress-down':''}">${d>0?'Naik +'+d:d<0?'Turun '+d:'Kekal'}</td>`;}).join('')}<td colspan="3">Pertengahan → Akhir</td></tr>`;
  const label=p.pbdSummary?.counts.map((n,i)=>n?'TP'+(6-i)+': '+n:'').filter(Boolean).join(' · ')||'Belum ditaksir';
  if(onlyPbd){body=body.replace(/<td class="rank"[\s\S]*?<\/td>/,'');body=body.replace(/(<small>[\s\S]*?<\/small>)/,`$1<small class="tp-distribution">${esc(label)} · ${p.pbdSummary?.assessed||0} ditaksir</small>`);}
  return `<tbody class="student-result">${body}</tbody>`;
 });f.assessment=oldMode;
 let result=`<div class="table-scroll"><table class="results-table"><thead><tr><th class="rank">${f.sort==='subject'?'Kedudukan subjek':'Kedudukan'}</th><th class="name">Nama murid / Kelas</th><th>Pentaksiran</th>${currentSubjects.map(s=>`<th>${esc(s)}</th>`).join('')}<th>Bil. A</th><th>Jumlah</th><th>Purata</th></tr></thead>${groups.join('')}</table></div>`;if(onlyPbd)result=result.replace(/<th class="rank">[\s\S]*?<\/th>/,'').replace('class="results-table"','class="results-table pbd-only-table"').replace('<th>Bil. A</th><th>Jumlah</th><th>Purata</th>','<th colspan="3">Penguasaan PBD</th>');return result;
}
function studentsView(){title('Keputusan murid','','MURID');$('#view').innerHTML=`${printTitle()}<section class="panel"><label class="screen-only">Cari nama murid<input id="search" type="search" placeholder="Taip nama murid…" value="${esc(search)}"></label>${toolbar()}<div id="results">${resultsTable(people.filter(p=>p.name.toLowerCase().includes(search.toLowerCase())))}</div></section>`;$('#search').oninput=e=>{search=e.target.value;$('#results').innerHTML=resultsTable(people.filter(p=>p.name.toLowerCase().includes(search.toLowerCase())));};}
function summaryTable(kind='pbd'){
 const rows=subjectSummary(people,currentSubjects).filter(r=>kind==='marks'?people.some(p=>p.marks[r.subject]):people.some(p=>chartPbdRecords(p,r.subject).length));
 if(!rows.length)return emptyData(kind==='marks'?'Belum ada markah dalam pilihan ini.':'Belum ada TP sah dalam pilihan ini.');
 const cols=kind==='marks'?['Ditaksir','Purata','A','B','C','D','E','F']:['Ditaksir','TP1','TP2','TP3','TP4','TP5','TP6'];
 return `<div class="table-scroll"><table class="analysis-table"><thead><tr><th class="name">Subjek</th>${cols.map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td class="name"><strong>${esc(r.subject)}</strong><small>${esc(SUBJECTS[r.subject]||r.subject)}</small></td>${kind==='marks'?`<td>${r.marks}</td><td>${r.average===null?'—':r.average.toFixed(1)+'%'}</td>${r.grades.map((n,i)=>`<td><button class="cell-btn" data-grade="${['A','B','C','D','E','F'][i]}" data-chart-subject="${esc(r.subject)}">${n}</button></td>`).join('')}`:`<td>${r.tp.reduce((a,b)=>a+b,0)}</td>${r.tp.map((n,i)=>`<td><button class="cell-btn ${i<2?'attention-text':''}" data-tp="TP${i+1}" data-tp-subject="${esc(r.subject)}">${n}</button></td>`).join('')}`}</tr>`).join('')}</tbody></table></div>`;
}
function analysisView(){
 title('Analisis pencapaian','','ANALISIS');if(['pbd','marks'].includes(analysisTab))analysisTab=chooseDataTab(analysisTab);
 $('#view').innerHTML=`${printTitle()}${tabs([['pbd','PBD'],['marks','Peperiksaan'],['progress','Perkembangan'],['coverage','Status data']],analysisTab,'analysis-tab')}<section class="panel"><div class="panel-head"><h3>${{pbd:'Taburan TP mengikut subjek',marks:'Gred mengikut subjek',progress:'Pertengahan dan Akhir',coverage:'Liputan data mengikut kelas'}[analysisTab]}</h3>${infoButton(analysisTab==='progress'?'perkembangan':analysisTab==='pbd'?'tp':'markah')}</div>${analysisTab==='progress'?comparison():analysisTab==='coverage'?classStatus():summaryTable(analysisTab)}</section>`;
}
function comparison(){
 const rows=selectRows(state.records,f),subs=[...new Set(rows.filter(r=>['PBD_MID','PBD_END'].includes(r.assessment)).map(r=>r.subject))].sort((a,b)=>Object.keys(SUBJECTS).indexOf(a)-Object.keys(SUBJECTS).indexOf(b));
 return subs.map(sub=>{const mid=rows.filter(r=>r.subject===sub&&r.assessment==='PBD_MID'&&/^TP[1-6]$/.test(r.tp)),end=rows.filter(r=>r.subject===sub&&r.assessment==='PBD_END'&&/^TP[1-6]$/.test(r.tp));const m=new Map(mid.map(r=>[r.studentKey,r]));const pairs=end.filter(r=>m.has(r.studentKey));const up=pairs.filter(r=>Number(r.tp.slice(2))>Number(m.get(r.studentKey).tp.slice(2))).length,down=pairs.filter(r=>Number(r.tp.slice(2))<Number(m.get(r.studentKey).tp.slice(2))).length;
 return `<div class="progress-item"><div><strong>${esc(sub)}</strong><small>${pairs.length} pasangan murid</small></div>${pairs.length?`<div class="progress-counts"><span class="progress-up">${up}<small>Meningkat</small></span><span>${pairs.length-up-down}<small>Kekal</small></span><span class="progress-down">${down}<small>Menurun</small></span></div>`:'<p class="hint">Belum ada pasangan Pertengahan–Akhir.</p>'}</div>`;
 }).join('')||emptyData('Belum ada rekod untuk perbandingan.');
}
function classStatus(){
 const groups=[...new Set(people.map(p=>p.year+' '+p.className))].sort();
 return groups.map(k=>{const ps=people.filter(p=>p.year+' '+p.className===k),tp=ps.filter(p=>chartPbdRecords(p,f.subject).length).length,marks=ps.filter(p=>p.complete).length;return `<div class="list-item"><strong>${esc(k)}</strong><div class="coverage-counts"><span>${ps.length} murid</span><span>${tp} dengan TP sah</span><span>${marks} markah lengkap</span></div></div>`;}).join('')||emptyData('Tiada kelas dalam pilihan ini.');
}
function profile(key){const p=people.find(x=>x.key===key);if(!p)return;const subs=[...new Set([...Object.keys(p.marks),...Object.keys(p.pbd)])];if(p.assessmentViews){modal('Profil pencapaian',`<button class="btn secondary no-print" data-action="slip">Cetak slip murid</button><h2>${esc(p.name)}</h2><p>${esc(assessmentName())} · ${esc(f.session)}</p>${resultsTable([p])}`);return;}modal('Profil pencapaian',`<button class="btn secondary no-print" data-action="slip">Cetak slip murid</button><h2>${esc(p.name)}</h2><p class="hint">${p.year} ${esc(p.className)} · Sesi ${esc(f.session)} · ${esc(assessmentName())}</p><div class="profile-grid">${kpi('Bilangan A',p.aCount,'UASA / MPT4')}${kpi('Jumlah',p.total,'Markah ditaksir')}${kpi('Purata',p.average?.toFixed(2)||'—','Peratus')}</div><div class="table-scroll"><table><thead><tr><th>Subjek</th><th>Markah</th><th>Gred</th><th>PBD</th></tr></thead><tbody>${subs.map(s=>`<tr><td>${esc(s)}</td><td>${p.marks[s]?.mark??esc(p.marks[s]?.status||'—')}</td><td>${p.marks[s]?.grade?`<span class="badge grade-badge grade-${esc(p.marks[s].grade)}">${esc(p.marks[s].grade)}</span>`:'—'}</td><td>${esc(p.pbd[s]?.tp||'—')}</td></tr>`).join('')}</tbody></table></div>${subs.filter(s=>p.pbd[s]?.comment||p.pbd[s]?.effort).map(s=>`<div class="list-item"><strong>${esc(SUBJECTS[s]||s)}</strong><p>${esc(p.pbd[s].comment)}</p><small>Usaha: ${esc(p.pbd[s].effort||'—')}</small></div>`).join('')}`);}
function interventionView(){
 title('Bimbingan dan tindakan','','INTERVENSI');const focus=people.filter(p=>chartPbdRecords(p,f.subject).some(r=>/^TP[12]$/.test(r.tp)));
 $('#view').innerHTML=`${printTitle()}<section class="panel workspace-entry"><div><h3>Ruang kerja guru</h3><p>Rekod kelompok, individu, program dan pemantauan.</p></div><button class="btn" data-action="teacher">${teacher?'Buka ruang kerja':'Log masuk guru'}</button></section><details class="panel disclosure" open><summary>Murid sasaran <span class="badge warn">${focus.length} murid TP1 / TP2</span></summary><div class="disclosure-body">${focus.map(p=>`<div class="list-item"><button class="text-btn" data-profile="${esc(p.key)}">${esc(p.name)}</button><small> · ${p.year} ${esc(p.className)}</small><p>${chartPbdRecords(p,f.subject).filter(r=>/^TP[12]$/.test(r.tp)).map(r=>`<span class="badge warn">${esc(r.subject)} ${esc(r.tp)}</span>`).join(' ')}</p></div>`).join('')||'<p class="hint">Tiada murid TP1 / TP2 dalam pilihan ini.</p>'}</div></details>`;
}
function teacherLogin(){modal('Akses guru',`<form id="teacher-login" class="form-grid"><label class="full">E-mel DELIMa<input name="email" type="email" autocomplete="username" required></label><label class="full">PIN Guru<input name="password" type="password" autocomplete="current-password" required></label><button class="btn full">Masuk ruang kerja</button><p class="hint full" id="login-status"></p></form>`);$('#teacher-login').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);const credentials={teacherEmail:fd.get('email'),teacherPin:fd.get('password')};await busy(e.target,async()=>{const data=await request('get_teacher_workspace',{session:f.session,...credentials});teacher={...credentials,data};showTeacherWorkspace();});};}
async function showTeacherWorkspace(){if(!teacher)return teacherLogin();try{teacher.data=await request('get_teacher_workspace',{session:f.session,teacherEmail:teacher.teacherEmail,teacherPin:teacher.teacherPin});}catch(e){toast(e.message);return;}const d=teacher.data;modal('Ruang kerja guru',`<p><strong>${esc(d.teacher.name)}</strong> · ${esc(d.teacher.role)}</p><div class="actions"><button class="btn secondary" data-work="group">Kelompok</button><button class="btn secondary" data-work="individual">Individu</button><button class="btn secondary" data-work="program">Program</button><button class="text-btn" data-action="teacher-out">Log keluar</button></div>${[...(d.groups||[]).map(r=>({...r,kind:'KELOMPOK'})),...(d.individuals||[]).map(r=>({...r,kind:'INDIVIDU'})),...(d.programs||[]).map(r=>({...r,kind:'PROGRAM'}))].map(r=>`<div class="list-item"><strong>${esc(r.groupName||r.studentName||r.programName)}</strong><p>${esc(r.subject)} · ${esc(r.status)}</p><p>${esc(r.interventionAction||r.activities||r.issue)}</p><button class="text-btn" data-monitor="${esc(r.id)}" data-kind="${r.kind}">Tambah pemantauan</button></div>`).join('')||'<p class="hint">Belum ada rekod tindakan untuk akaun ini.</p>'}`);}
function workForm(kind){if(!teacher)return teacherLogin();const ps=people.filter(p=>!f.year||p.year===Number(f.year));modal(kind==='program'?'Program panitia':kind==='group'?'Intervensi kelompok':'Intervensi individu',`<p class="hint">Pilih tahun, kelas dan subjek pada penapis utama sebelum merekod intervensi. Sesi ${esc(f.session)}.</p><form id="work-form" class="form-grid"><label>Subjek<select name="subject">${currentSubjects.map(s=>option(s,SUBJECTS[s]||s,f.subject)).join('')}</select></label>${kind==='program'?'<label>Nama program<input name="programName" required></label>':`<label>Tahun<input name="year" type="number" min="1" max="6" value="${esc(f.year||4)}" required></label><label>Kelas<select name="className">${[...new Set(ps.map(p=>p.className))].map(c=>option(c,c,f.className)).join('')}</select></label><label>TP asal<select name="originalTp">${[1,2,3,4,5,6].map(n=>option('TP'+n,'TP'+n,'TP2')).join('')}</select></label>${kind==='group'?'<label class="full">Nama kelompok<input name="groupName" required></label>':''}<fieldset class="full checklist"><legend>${kind==='group'?'Pilih murid (kelas dan tahun mesti sepadan)':'Pilih seorang murid'}</legend>${ps.map(p=>`<label><input type="${kind==='group'?'checkbox':'radio'}" name="member" value="${esc(p.key)}">${esc(p.name)} · ${p.year} ${esc(p.className)}</label>`).join('')}</fieldset>`}<label class="full">Isu / kemahiran<textarea name="issue" required></textarea></label><label class="full">Objektif<textarea name="objective" required></textarea></label><label class="full">Aktiviti / tindakan<textarea name="interventionAction" required></textarea></label><label>Tarikh mula<input type="date" name="startDate" required></label><label>Tarikh semakan<input type="date" name="reviewDate" required></label><label class="full">Sasaran / petunjuk kejayaan<input name="target" required></label><label>Status<select name="status"><option>DIRANCANG</option><option>SEDANG DILAKSANAKAN</option><option>SELESAI</option></select></label><button class="btn full">Simpan tindakan</button><p class="hint full" id="form-status"></p></form>`);$('#work-form').onsubmit=async e=>{e.preventDefault();await busy(e.target,async()=>{const fd=new FormData(e.target);const b=Object.fromEntries(fd);delete b.member;b.session=f.session;b.teacherEmail=teacher.teacherEmail;b.teacherPin=teacher.teacherPin;const selected=fd.getAll('member').map(key=>ps.find(p=>p.key===key));if(kind!=='program'){if(!selected.length)throw Error('Pilih murid dahulu.');if(selected.some(p=>p.year!==Number(b.year)||p.className!==b.className))throw Error('Murid pilihan mesti dalam tahun dan kelas yang dinyatakan.');if(kind==='group')b.members=selected.map(p=>({studentName:p.name,studentKey:p.key,tpBefore:p.pbd[b.subject]?.tp||b.originalTp}));else{b.studentName=selected[0].name;b.studentKey=selected[0].key;}}else{b.activities=b.interventionAction;b.successIndicator=b.target;b.endDate=b.reviewDate;b.targetGroup=f.year?'Tahun '+f.year:'Mengikut sasaran panitia';}await request({group:'save_group_intervention',individual:'save_individual_intervention',program:'save_panitia_program'}[kind],b);toast('Tindakan berjaya disimpan.');await showTeacherWorkspace();});};}
function monitorForm(id,kind){modal('Rekod pemantauan',`<form id="monitor-form" class="form-grid"><label class="full">Perkembangan<textarea name="progress" required></textarea></label><label class="full">Hasil / impak<textarea name="result"></textarea></label><label class="full">Tindakan seterusnya<textarea name="nextAction"></textarea></label><label>Semakan berikutnya<input type="date" name="nextReviewDate"></label><label>Status<select name="status"><option>SEDANG DILAKSANAKAN</option><option>SELESAI</option></select></label><button class="btn full">Simpan pemantauan</button><p class="hint full" id="form-status"></p></form>`);$('#monitor-form').onsubmit=async e=>{e.preventDefault();await busy(e.target,async()=>{await request('save_monitoring',{...Object.fromEntries(new FormData(e.target)),referenceType:kind,referenceId:id,teacherEmail:teacher.teacherEmail,teacherPin:teacher.teacherPin});toast('Pemantauan disimpan.');showTeacherWorkspace();});};}
function reportsView(){
 title('Cetakan dan eksport','','LAPORAN');
 $('#view').innerHTML=`${printTitle()}<section class="panel report-controls"><label>Jenis laporan<select id="report-kind">${[['students','Keputusan murid'],['pbd','Ringkasan PBD'],['marks','Ringkasan peperiksaan']].map(([id,label])=>option(id,label,reportType==='dialog'?'students':reportType)).join('')}</select></label><div class="actions"><button class="btn" data-action="print">Cetak / PDF</button><button class="btn secondary" data-action="report-csv">Muat turun CSV</button></div></section><section class="panel report-content"><div class="panel-head"><h3>${{students:'Keputusan murid',pbd:'Ringkasan PBD',marks:'Ringkasan peperiksaan'}[reportType]||'Keputusan murid'}</h3><span class="badge">${people.length} murid</span></div>${reportType==='pbd'?summaryTable('pbd'):reportType==='marks'?summaryTable('marks'):resultsTable(people)}</section><section class="panel report-dialog-entry"><div><h3>Dialog Prestasi</h3><p>Dapatan, punca dan pelan tindakan untuk pembentangan.</p></div><button class="btn secondary" data-go="dialog">Sediakan pembentangan</button></section>`;
 $('#report-kind').onchange=e=>{reportType=e.target.value;reportsView();};
}
function showInfo(topic){
 const content={ranking:['Susunan murid','Bilangan A terbanyak, kemudian jumlah markah. Seri berkongsi kedudukan (1, 1, 3). Dikira mengikut tahun dan kumpulan subjek sama; T/TD tidak dianggap sifar. Pilihan TP6 menyusun taburan TP tanpa nombor kedudukan.'],tp:['Bacaan carta PBD','Setiap murid dikira sekali bagi setiap TP. Jika semua subjek dipilih, murid boleh muncul dalam beberapa TP. Penguasaan TP3–TP6 dikira daripada rekod subjek yang ditaksir. Apabila Akhir dipilih, carta menggunakan Akhir; selainnya Pertengahan. Klik palang atau bilangan untuk senarai murid.'],markah:['Bacaan carta markah','Carta memisahkan bawah ambang, mencapai ambang dan T/TD. Markah kurang daripada ambang dipilih ditonjolkan dalam oren. T/TD dan rekod belum ditaksir tidak dianggap gagal; tiada rekod subjek tidak dianggap sifar. Jika beberapa pentaksiran dipilih, markah mengikut pentaksiran utama jadual murid.'],perkembangan:['Perbandingan PBD','Perkembangan menggunakan pasangan ID murid dan subjek yang sama antara Pertengahan dan Akhir dalam sesi dipilih. Murid tanpa pasangan rekod tidak dianggap meningkat atau menurun.']};
 const [title,text]=content[topic]||content.ranking;modal(title,`<p>${text}</p>`);
}
function dialogView(){title('Dialog Prestasi','','LAPORAN');const m=metrics();const key='sap.dialog.'+f.session+'.'+selectedAssessments().join('-')+'.'+f.year+'.'+f.subject;let draft;try{draft=JSON.parse(localStorage.getItem(key)||'{}');}catch(e){draft={};}$('#view').innerHTML=`<button class="text-btn screen-only" data-go="reports">Kembali ke Laporan</button><div class="actions"><button class="btn" data-action="print">Cetak slaid / PDF</button><button class="btn secondary" id="export-pptx">Muat turun PowerPoint</button><span class="hint">Draf dialog disimpan pada peranti ini.</span></div><section class="slide"><p class="eyebrow">SK TEMIN · SESI ${esc(f.session)}</p><h2>Dialog Prestasi Akademik</h2><p>${esc(assessmentName())} · ${esc($('#scope-label').textContent)}</p><div class="kpi-grid">${kpi('Murid',people.length,'Dalam skop')}${kpi('Purata markah',m.avg?.toFixed(2)||'—','Rekod ditaksir')}${kpi('Penguasaan PBD',m.mastery===null?'—':m.mastery.toFixed(1)+'%','TP3–TP6')}${kpi('Fokus intervensi',m.focus,'Murid TP1/TP2')}</div></section><section class="slide"><h2>Dapatan utama</h2>${subjectBars(m.marks)}<p>TP1–TP2: ${m.tp.filter(r=>/^TP[12]$/.test(r.tp)).length} rekod daripada ${m.tp.length} rekod TP.</p></section><section class="slide"><h2>Analisis punca untuk disahkan</h2><p class="hint">Punca tidak boleh ditentukan daripada markah sahaja. Isi berdasarkan perbincangan dan evidens.</p><div class="fishbone">${['Murid','Guru','Kaedah PdP','Pentaksiran','Bahan & kemudahan','Persekitaran'].map((label,i)=>`<article><strong>${label}</strong><textarea data-draft="cause${i}" placeholder="Punca yang telah dikenal pasti…">${esc(draft['cause'+i]||'')}</textarea></article>`).join('')}</div></section><section class="slide"><h2>Pelan tindakan & impak</h2><div class="form-grid">${[['issue','Isu utama'],['action','Intervensi / tindakan'],['pic','Guru bertanggungjawab'],['period','Tempoh'],['target','Petunjuk kejayaan'],['impact','Impak selepas pelaksanaan']].map(([k,l])=>`<label>${l}<textarea data-draft="${k}">${esc(draft[k]||'')}</textarea></label>`).join('')}</div></section>`;document.querySelectorAll('[data-draft]').forEach(el=>el.oninput=()=>{draft[el.dataset.draft]=el.value;localStorage.setItem(key,JSON.stringify(draft));});$('#export-pptx').onclick=async()=>{try{await exportPowerPoint(m,draft);}catch(e){toast(e.message);}};}
async function exportPowerPoint(m,draft){if(!window.PptxGenJS)await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='vendor/pptxgen.bundle.js';s.onload=resolve;s.onerror=()=>reject(Error('Fail PowerPoint tidak dapat dimuatkan.'));document.head.append(s);});const pptx=new window.PptxGenJS();pptx.layout='LAYOUT_WIDE';pptx.author='SK TEMIN';pptx.subject='Dialog Prestasi SAP-TEMIN';const add=(title,lines)=>{const slide=pptx.addSlide();slide.background={color:'F2F6F8'};slide.addText('SAP-TEMIN · SK TEMIN · '+f.session,{x:.6,y:.4,w:12,h:.3,fontSize:12,color:'007E7B'});slide.addText(title,{x:.6,y:1,w:12,h:.8,fontSize:30,bold:true,color:'133246'});slide.addText(lines.join('\n\n'),{x:.7,y:2,w:11.8,h:4.6,fontSize:19,color:'133246',breakLine:false,fit:'shrink'});};add('Dialog Prestasi Akademik',[assessmentName(),$('#scope-label').textContent,`${people.length} murid · Purata markah ${m.avg?.toFixed(2)||'—'} · Penguasaan PBD ${m.mastery?.toFixed(1)||'—'}%`]);add('Dapatan utama',currentSubjects.map(s=>{const r=m.marks.filter(r=>r.subject===s);return `${SUBJECTS[s]||s}: ${r.length?(r.reduce((a,v)=>a+v.mark,0)/r.length).toFixed(2):'—'} (${r.length} rekod markah)`;}));add('Analisis punca',['Murid','Guru','Kaedah PdP','Pentaksiran','Bahan & kemudahan','Persekitaran'].map((v,i)=>v+': '+(draft['cause'+i]||'Belum disahkan')));add('Pelan tindakan',[`Isu: ${draft.issue||'—'}`,`Tindakan: ${draft.action||'—'}`,`PIC: ${draft.pic||'—'} · Tempoh: ${draft.period||'—'}`,`Sasaran: ${draft.target||'—'}`,`Impak: ${draft.impact||'Belum dinilai'}`]);await pptx.writeFile({fileName:`SAP-TEMIN-Dialog-${f.session}.pptx`});}
function settingsView(){if(!admin){toast('Menu ini untuk admin sahaja.');return;}title('Sambungan pangkalan data.','Tetapan ini disimpan pada peranti yang digunakan.','TETAPAN');$('#view').innerHTML=`<button class="text-btn screen-only" data-go="admin">Kembali ke Admin</button><section class="panel"><form id="settings-form"><label>URL Web App Apps Script v3<input name="url" type="url" value="${esc(apiUrl)}" placeholder="https://script.google.com/macros/s/…/exec" required></label><p class="hint">Gunakan deployment daripada fail server/Code.gs yang dibekalkan. Pangkalan data lama kekal; jalankan setupSAPTEMINv3 sekali sebelum menyambung.</p><div class="actions"><button class="btn">Simpan & sambung</button><button type="button" class="btn secondary" data-action="demo">Guna data contoh</button></div><p id="form-status" class="hint"></p></form></section>`;$('#settings-form').onsubmit=async e=>{e.preventDefault();const url=String(new FormData(e.target).get('url')).trim();if(!/^https:\/\/script\.google\.com\/(?:a\/macros\/[A-Za-z0-9.-]+|macros)\/s\/[A-Za-z0-9_-]+\/exec$/.test(url)){toast('Gunakan URL Apps Script rasmi yang berakhir /exec.');return;}await busy(e.target,async()=>{const prior=apiUrl;apiUrl=url;try{const info=await request('manifest_v3');if(info.apiVersion!=='3.0.0'||!info.version)throw Error('Web App ini belum tersedia. Pasang kod v3 dan jalankan setupSAPTEMINv3 dahulu.');}catch(err){apiUrl=prior;throw err;}admin=null;teacher=null;localStorage.setItem('sap.v3.api',url);state={...state,records:[],version:'',demo:false,preview:false};originalOnline=null;initFilters();render();await sync(true);});};}
function helpView(){title('Panduan penggunaan','','PANDUAN');$('#view').innerHTML=`<section class="panel"><h2>Menu bawah sahaja</h2><p>Utama untuk ringkasan. Analisis untuk pecahan subjek dan kelas. Murid untuk keputusan dan ranking. Intervensi untuk tindakan susulan. Laporan untuk cetakan, eksport dan Dialog Prestasi. Ikon ? membuka panduan. Alat pratonton dan sambungan hanya tersedia selepas admin log masuk.</p><h3>Keputusan Tahun 4</h3><p>UASA + MPT4 mengambil BM, BI, Matematik dan Sains daripada MPT4. Subjek lain daripada UASA. PBD Akhir dipaparkan berasingan pada baris bawah.</p><h3>Ranking</h3><p>Bilangan A terbanyak, kemudian jumlah tertinggi. Jika kedua-duanya sama, kedudukan bersama (1, 1, 3). Perbandingan dalam tahun dan kumpulan subjek yang sama sahaja. T / TD tidak dianggap sifar dan keputusan belum lengkap tidak diberi kedudukan.</p><h3>Untuk admin</h3><p>Tekan logo SK Temin tiga kali dalam masa singkat. Log masuk dengan e-mel ADMIN aktif dan PIN dalam AKSES_GURU. Pilih sesi dan pentaksiran, muat naik fail, semak pratonton, kemudian sahkan simpan.</p><h3>Fail yang disokong versi ini</h3><p>JSON classes/students/subjects seperti fail contoh PBD dan UASA yang dibekalkan. PDF MPT4 berteks dengan lajur JUMLAH daripada 50. PDF imbasan dan format Excel/CSV belum disokong dalam binaan ini.</p><h3>Data tahun lama</h3><p>Tambah sesi baharu tanpa reset. Kunci sesi lama sebagai arkib. Sandaran dibuat sebelum perubahan data v3; helaian dan rekod lama dikekalkan.</p></section>`;}
function adminLogin(){if(!apiUrl){toast('Sambungan pusat belum ditetapkan. Hubungi pentadbir sistem.');return;}modal('Log masuk admin',`<form id="admin-login" class="form-grid"><label class="full">E-mel admin<input name="email" type="email" required autocomplete="username"></label><label class="full">Kata laluan / PIN admin<input name="password" type="password" required autocomplete="current-password"></label><button class="btn full">Log masuk</button><p class="hint full" id="login-status">Disahkan di pelayan. Sesi admin disimpan dalam memori sahaja.</p></form>`);$('#admin-login').onsubmit=async e=>{e.preventDefault();await busy(e.target,async()=>{const d=await request('v3_login',Object.fromEntries(new FormData(e.target)));admin={token:d.authToken,name:d.name};toast('Log masuk berjaya.');go('admin');});};}
function adminView(){if(!admin){go('home');adminLogin();return;}title('Pengurusan data sekolah.','Upload, sesi, pentaksiran dan sandaran dalam satu ruang.','ADMIN · '+admin.name);$('#view').innerHTML=`<section class="panel"><div class="panel-head"><h3>Upload data</h3><button class="btn secondary" data-action="admin-out">Log keluar</button></div>${uploadForm(true)}</section><section class="panel"><h3>Alat admin</h3><div class="actions"><button class="btn" data-go="placement">Penyusunan Kelas</button><button class="btn secondary" data-go="preview">Pratonton fail</button><button class="btn secondary" data-go="settings">Sambungan pusat</button></div></section><section class="panel"><h3>Sesi persekolahan</h3><p class="hint">Sesi lama dikekalkan. Sesi dikunci masih boleh dilihat tetapi tidak boleh diimport.</p>${state.config.sessions.map(s=>`<div class="list-item"><strong>${esc(s.year)}</strong> <span class="badge ${s.locked?'warn':''}">${s.locked?'Arkib / dikunci':'Terbuka'}${state.config.activeSession===s.year?' · Sesi lalai':''}</span><div class="actions"><button class="btn secondary" data-lock="${s.year}" data-locked="${!s.locked}">${s.locked?'Buka kunci':'Kunci sesi'}</button><button class="text-btn" data-active="${s.year}">Jadikan sesi lalai</button></div></div>`).join('')}<form id="add-session" class="actions"><label>Sesi baharu<input name="year" type="number" min="2000" max="2099" value="${Number(state.config.activeSession)+1}" required></label><button class="btn">＋ Tambah sesi</button></form></section><section class="panel"><h3>Pentaksiran</h3><p class="hint">${state.config.assessments.map(a=>esc(a.name)+' ('+a.type+')').join(' · ')}</p><form id="add-assessment" class="form-grid"><label>Nama pentaksiran<input name="name" required></label><label>Jenis<select name="type"><option value="MARKAH">Markah</option><option value="TP">Tahap Penguasaan</option></select></label><button class="btn">＋ Tambah pentaksiran</button></form></section><section class="panel"><h3>Sandaran & pemulihan</h3><p class="hint">Sandaran automatik sebelum setiap import/perubahan. Pemulihan v3 tidak memadam atau menulis semula helaian PBD/intervensi lama.</p><div class="actions"><button class="btn" data-action="backup">Buat & muat turun sandaran</button><button class="btn secondary" data-action="backups">Senarai sandaran</button></div><label>Pulihkan fail sandaran v3<input type="file" id="restore-file" accept=".json,application/json"></label></section>`;bindUpload(true);$('#add-session').onsubmit=async e=>{e.preventDefault();await changeConfig({operation:'add_session',year:new FormData(e.target).get('year')});};$('#add-assessment').onsubmit=async e=>{e.preventDefault();await changeConfig({operation:'add_assessment',...Object.fromEntries(new FormData(e.target))});};$('#restore-file').onchange=async e=>{try{const d=JSON.parse(await e.target.files[0].text());confirmRestore({data:d});}catch(err){toast(err.message);}};}
let placementDraft=null,placementUi=null;
function placementDefaults(){const y=Number(f.year)||4,session=f.session;const inYear=state.records.filter(r=>String(r.session)===session&&r.year===y);const basis=inYear.some(r=>r.assessment==='UASA')?'COMBINED':inYear.some(r=>r.assessment==='PBD_END')?'PBD_END':'PBD_MID';const count=Math.min(4,Math.max(1,new Set(inYear.map(r=>r.className)).size));return {sourceSession:session,sourceYear:y,basis,targetSession:String(Number(session)+1),targetYear:Math.min(6,y+1),count};}
function placementRoster(){return placementStudents(viewData(state.records,{session:$('#place-session').value,year:$('#place-year').value,assessment:$('#place-basis').value,assessments:[$('#place-basis').value],className:'',subject:'',sort:'rank'}),$('#place-basis').value);}
function roomFields(n,count){const rooms=balancedRooms(n,count);$('#place-rooms').innerHTML=rooms.map((room,i)=>`<label>Kelas ${i+1}<select id="place-class-${i}">${CLASS_NAMES.map(c=>option(c,c,placementDraft?.rooms.length===count?placementDraft.rooms[i].name:room.name)).join('')}</select></label><label>Kuota murid<input id="place-cap-${i}" type="number" min="0" max="2000" value="${room.capacity}" required></label>`).join('');updateEliteOptions();}
function updateEliteOptions(){const count=Number($('#place-count').value),names=Array.from({length:count},(_,i)=>$('#place-class-'+i)?.value).filter(Boolean);$('#place-elite').innerHTML=names.map(c=>option(c,c,placementDraft?.eliteClass||names[0])).join('');$('#place-elite-field').hidden=$('#place-method').value!=='elite';}
function refreshPlacementSource(){const list=placementRoster(),cohorts=new Map();for(const p of list.filter(p=>p.eligible))cohorts.set(p.subjects,(cohorts.get(p.subjects)||0)+1);const groups=[...cohorts.entries()].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]));$('#place-cohort').innerHTML=groups.map(([key,n])=>option(key,key.split('|').join(', ')+' · '+n+' murid',placementDraft?.cohort||groups[0]?.[0])).join('')||option('','Tiada keputusan lengkap','');$('#place-source-count').textContent=list.length+' murid · '+list.filter(p=>!p.eligible).length+' belum lengkap';roomFields(list.length,Number($('#place-count').value));}
function placementView(){
 if(!admin){toast('Menu ini untuk admin sahaja.');return;}placementUi??=placementDefaults();const u=placementUi;
 title('Penyusunan Kelas','','ADMIN');
 $('#view').innerHTML=`<button class="text-btn screen-only" data-go="admin">Kembali ke Admin</button><section class="panel placement-setup"><div class="panel-head"><h3>Tetapkan cadangan kelas</h3><span id="place-source-count" class="badge"></span></div><p class="hint">Cadangan diasingkan daripada kelas asal. Tiada rekod murid dalam Google Sheets diubah.</p><form id="placement-form"><div class="form-grid"><label>Sesi sumber<select id="place-session">${state.config.sessions.map(s=>option(s.year,s.year,u.sourceSession)).join('')}</select></label><label>Tahun sumber<select id="place-year">${[1,2,3,4,5,6].map(y=>option(y,'Tahun '+y,u.sourceYear)).join('')}</select></label><label>Asas pencapaian<select id="place-basis">${['COMBINED','UASA','MPT4','PBD_END','PBD_MID'].map(id=>option(id,assessmentLabel(id),u.basis)).join('')}</select></label><label>Kumpulan subjek untuk agihan automatik<select id="place-cohort"></select></label><label>Sesi baharu<input id="place-target-session" type="number" min="2000" max="2099" value="${esc(u.targetSession)}" required></label><label>Tahun baharu<select id="place-target-year">${[1,2,3,4,5,6].map(y=>option(y,'Tahun '+y,u.targetYear)).join('')}</select></label><label>Bilangan kelas<select id="place-count">${[1,2,3,4].map(n=>option(n,n+' kelas',u.count)).join('')}</select></label><label>Kaedah agihan<select id="place-method">${[['snake','Semua kelas campuran seimbang (ular)'],['elite','1 kelas cemerlang + baki campuran'],['round','Giliran ranking A–B–C–D'],['manual','Tetapkan manual, kemudian agih baki']].map(([id,label])=>option(id,label,placementDraft?.method||'snake')).join('')}</select></label></div><div id="place-rooms" class="placement-room-fields"></div><label id="place-elite-field">Kelas cemerlang<select id="place-elite"></select></label><p class="hint">Murid dengan kumpulan subjek berbeza atau keputusan belum lengkap diletakkan dalam Semakan Manual. Kuota merangkumi semua murid sumber.</p><div class="actions"><button class="btn" type="submit">Jana cadangan</button><button class="btn secondary" type="button" id="place-info">Cara agihan</button></div><p class="hint" id="place-error" role="status"></p></form></section><details class="panel disclosure placement-drafts"><summary>Draf simpanan dan sandaran</summary><div class="disclosure-body"><p class="hint">Draf disimpan pada pelayar ini. Muat turun JSON untuk salinan yang boleh dibawa ke peranti lain.</p><label>Draf tersimpan<select id="place-saved"><option value="">Pilih draf</option>${readPlacementDrafts().map(d=>option(d.id,d.name+' · '+formatDate(d.savedAt),'')).join('')}</select></label><label>Pulihkan draf JSON<input type="file" id="place-restore" accept=".json,application/json"></label></div></details><div id="placement-results"></div>`;
 refreshPlacementSource();if(placementDraft){for(let i=0;i<placementDraft.rooms.length;i++)if($('#place-cap-'+i))$('#place-cap-'+i).value=placementDraft.rooms[i].capacity;}
 for(const id of ['place-session','place-year','place-basis','place-count'])$('#'+id).onchange=()=>{refreshPlacementSource();};
 $('#place-rooms').onchange=updateEliteOptions;$('#place-method').onchange=updateEliteOptions;
 $('#place-info').onclick=()=>modal('Kaedah penyusunan',`<p><strong>Ular:</strong> agih 1–2–3–4 kemudian 4–3–2–1. <strong>Giliran:</strong> ulang 1–2–3–4.</p><p><strong>Kelas cemerlang:</strong> isi kelas pilihan mengikut kuota dengan pencapaian teratas, kemudian agih baki secara ular.</p><p>Peperiksaan menggunakan bilangan A kemudian jumlah. PBD menggunakan bilangan TP6, TP5 hingga TP1. Agihan automatik membandingkan kumpulan subjek yang sama. Keputusan seri diputuskan mengikut nama A–Z untuk urutan agihan sahaja; semak sempadan kuota.</p><p>Tukar kelas melalui dropdown nama murid untuk menetapkan penempatan tetap. Jana semula akan mengekalkannya apabila sumber sama. Ringkasan ialah cadangan untuk semakan sekolah, bukan pindaan kelas asal.</p>`);
 $('#placement-form').onsubmit=e=>{e.preventDefault();try{const students=placementRoster();if(!students.length)throw Error('Tiada murid bagi sesi, tahun dan pentaksiran ini.');const count=Number($('#place-count').value);const settings={sourceSession:$('#place-session').value,sourceYear:Number($('#place-year').value),basis:$('#place-basis').value,targetSession:$('#place-target-session').value,targetYear:Number($('#place-target-year').value),rooms:Array.from({length:count},(_,i)=>({name:$('#place-class-'+i).value,capacity:Number($('#place-cap-'+i).value)})),method:$('#place-method').value,eliteClass:$('#place-elite').value,cohort:$('#place-cohort').value,sourceVersion:state.version,name:placementDraft?.name||'Cadangan '+$('#place-target-session').value};const same=placementDraft&&['sourceSession','sourceYear','basis'].every(k=>String(placementDraft[k])===String(settings[k]));placementDraft=generatePlacement(students,settings,same?placementDraft.fixed:{});placementUi={...settings,count};$('#place-error').textContent='';renderPlacementResults();}catch(err){$('#place-error').textContent=err.message;}};
 $('#place-saved').onchange=e=>{const d=readPlacementDrafts().find(x=>x.id===e.target.value);if(d)loadPlacementDraft(d);};
 $('#place-restore').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('Fail draf melebihi 5 MB.');loadPlacementDraft(JSON.parse(await file.text()));}catch(err){toast(err.message);}};
 renderPlacementResults();
}
function readPlacementDrafts(){try{return JSON.parse(localStorage.getItem('sap.v3.placements')||'[]').filter(d=>d?.schema==='sap-temin-placement@1').slice(0,10);}catch{return [];}}
function loadPlacementDraft(d){try{validatePlan(d);placementDraft=JSON.parse(JSON.stringify(d));placementUi={...placementDraft,count:placementDraft.rooms.length};placementView();toast('Draf dibuka. Kelas asal tidak diubah.');}catch(err){toast(err.message);}}
function renderPlacementResults(){
 const out=$('#placement-results');if(!out||!placementDraft){if(out)out.innerHTML='';return;}const d=placementDraft,unplaced=d.students.filter(p=>!d.assignments[p.key]),stats=placementSummary(d);
 const row=p=>`<div class="placement-pupil"><div><strong>${esc(p.name)}</strong><small>${p.sourceYear} ${esc(p.sourceClass)}${d.order?.[p.key]?' · Turutan '+d.order[p.key]:''}${d.fixed[p.key]?' · Tetap':''}</small></div><select class="placement-move" data-pupil="${esc(p.key)}" aria-label="Kelas cadangan ${esc(p.name)}">${option('','Belum ditempatkan',d.assignments[p.key]||'')}${d.rooms.map(r=>option(r.name,r.name,d.assignments[p.key]||'')).join('')}</select></div>`;
 out.innerHTML=`<section class="panel placement-result-header"><div class="panel-head"><div><h3>Cadangan Tahun ${d.targetYear} · ${esc(d.targetSession)}</h3><p>${d.students.length-unplaced.length} ditempatkan · ${unplaced.length} semakan manual</p></div><span class="badge warn">Draf cadangan</span></div>${d.sourceVersion!==state.version?'<div class="notice warn">Data pusat telah berubah sejak draf ini dijana. Semak semula sebelum digunakan.</div>':''}${d.warnings.map(w=>`<p class="hint attention-text">${esc(w)}</p>`).join('')}<label class="screen-only">Nama draf<input id="place-name" value="${esc(d.name||'Cadangan kelas')}" maxlength="100"></label><div class="actions screen-only"><button class="btn" id="place-save">Simpan draf</button><button class="btn secondary" id="place-csv">CSV / Excel</button><button class="btn secondary" id="place-print">Cetak / PDF</button><button class="btn secondary" id="place-json">Sandaran JSON</button>${d.method==='manual'?'<button class="btn secondary" id="place-distribute">Agih baki secara ular</button>':''}</div></section><div class="placement-grid">${stats.map(room=>`<section class="panel placement-class"><div class="panel-head"><h3>${esc(room.name)}</h3><span class="badge ${room.count>=room.capacity?'warn':''}">${room.count} / ${room.capacity}</span></div>${d.basis.startsWith('PBD')?`<p class="placement-summary">${room.tpCounts.map((n,i)=>'TP'+(6-i)+': '+n).join(' · ')}</p>`:`<p class="placement-summary">Purata murid: ${room.average===null?'—':room.average.toFixed(1)+'%'}</p>`}<div class="placement-list">${d.students.filter(p=>d.assignments[p.key]===room.name).sort((a,b)=>a.name.localeCompare(b.name,'ms')).map(row).join('')||'<p class="hint">Belum ada murid.</p>'}</div></section>`).join('')}</div><details class="panel disclosure" ${unplaced.length?'open':''}><summary>Semakan manual <span class="badge warn">${unplaced.length} murid</span></summary><div class="disclosure-body placement-list">${unplaced.map(row).join('')||'<p class="hint">Semua murid telah ditempatkan.</p>'}</div></details><p class="hint screen-only">Penempatan manual menjadi tetap. Jika kelas penuh, kosongkan satu tempat dahulu sebelum memindahkan murid lain. Kiraan TP ialah bilangan rekod subjek; turutan agihan bukan nombor kedudukan rasmi.</p>`;
 out.onchange=e=>{const key=e.target.dataset.pupil;if(!key)return;try{placementDraft=movePlacement(placementDraft,key,e.target.value);renderPlacementResults();}catch(err){e.target.value=placementDraft.assignments[key]||'';toast(err.message);}};
 const setName=()=>{placementDraft.name=$('#place-name').value.trim()||'Cadangan kelas';};
 $('#place-name').oninput=e=>{placementDraft.name=e.target.value;};
 $('#place-save').onclick=()=>{try{setName();const item={...placementDraft,id:String(Date.now())+'-'+Math.random().toString(36).slice(2,8),savedAt:new Date().toISOString()};const drafts=readPlacementDrafts();if(drafts.length>=10)throw Error('Maksimum 10 draf pada pelayar ini. Muat turun JSON dahulu.');localStorage.setItem('sap.v3.placements',JSON.stringify([item,...drafts]));$('#place-saved').innerHTML='<option value="">Pilih draf</option>'+[item,...drafts].map(x=>option(x.id,x.name+' · '+formatDate(x.savedAt),'')).join('');toast('Draf disimpan pada pelayar ini.');}catch(err){toast('Draf belum disimpan: '+err.message+' Gunakan Sandaran JSON.');}};
 $('#place-csv').onclick=()=>{setName();download('PENYUSUNAN-KELAS-'+d.targetYear+'-'+d.targetSession+'.csv',placementCsv(placementDraft),'text/csv;charset=utf-8');};
 $('#place-json').onclick=()=>{setName();download('DRAF-KELAS-'+d.targetYear+'-'+d.targetSession+'.json',JSON.stringify(placementDraft,null,2),'application/json');};
 $('#place-print').onclick=()=>{const oldTitle=document.title;document.title='PENYUSUNAN KELAS TAHUN '+d.targetYear+' '+d.targetSession;document.body.classList.add('printing-placement');const cleanup=()=>{document.body.classList.remove('printing-placement');document.title=oldTitle;};window.addEventListener('afterprint',cleanup,{once:true});window.print();};
 if($('#place-distribute'))$('#place-distribute').onclick=()=>{try{setName();placementDraft=generatePlacement(placementDraft.students,{...placementDraft,method:'snake'},placementDraft.fixed);renderPlacementResults();}catch(err){toast(err.message);}};
}

function uploadForm(isAdmin){return `<form id="upload-form" class="form-grid"><label>Sesi<select name="session">${state.config.sessions.map(s=>option(s.year,s.year+(s.locked?' · Dikunci':''),state.config.activeSession)).join('')}</select></label><label>Pentaksiran<select name="assessment">${state.config.assessments.map(a=>option(a.id,a.name,'UASA')).join('')}</select></label><div class="upload-box full">${icon('upload')}<p>JSON PBD / UASA atau PDF MPT4</p><input name="files" type="file" accept=".json,.pdf,application/json,application/pdf" multiple required><p class="hint">Fail dibaca pada peranti. Hanya keputusan yang disahkan dihantar ketika Simpan.</p></div><button class="btn full">Baca & pratonton</button><p class="hint full" id="upload-status"></p></form><div id="import-preview"></div>`;}
function preview(){if(!admin){toast('Menu ini untuk admin sahaja.');return;}modal('Pratonton fail pada peranti',`<div class="notice warn">Mod pratonton sahaja. Tidak menghantar atau menyimpan data ke Google Sheets.</div>${uploadForm(false)}`);bindUpload(false);}
function bindUpload(isAdmin){$('#upload-form').onsubmit=async e=>{e.preventDefault();const form=e.target;await busy(form,async()=>{const fd=new FormData(form);const session=String(fd.get('session'));const a=state.config.assessments.find(a=>a.id===fd.get('assessment'));if(isAdmin&&state.config.sessions.find(s=>s.year===session)?.locked)throw Error('Sesi ini dikunci.');const files=fd.getAll('files');let rows=[];for(const file of files){if(file.size>30*1024*1024)throw Error('Fail melebihi 30 MB.');$('#upload-status').textContent='Membaca '+file.name+'…';if(file.name.toLowerCase().endsWith('.pdf')){if(a.id!=='MPT4')throw Error('Pilih pentaksiran MPT4 untuk fail PDF.');rows.push(...await parseMptPdf(file,session,msg=>$('#upload-status').textContent=msg));}else{const d=JSON.parse((await file.text()).replace(/^\uFEFF/,''));if(String(d.sessionYear)!==session)throw Error('Sesi dalam JSON tidak sama dengan sesi pilihan.');if(a.id==='UASA'&&!String(d.schema).includes('uasa'))throw Error('Fail bukan JSON UASA.');if(a.type==='TP'&&!String(d.schema).includes('pbd'))throw Error('Fail bukan JSON PBD.');if(a.id==='PBD_END'&&!String(d.schema).includes('akhir'))throw Error('Pilih pentaksiran yang sepadan dengan JSON.');if(a.id==='PBD_MID'&&String(d.schema).includes('akhir'))throw Error('Fail ini PBD Akhir, bukan Pertengahan.');rows.push(...await parseJson(d,a,session));}}const errors=validateRecords(rows);if(errors.length)throw Error(errors.slice(0,8).join('\n'));const existing=new Set(state.records.map(recordKey));const updated=rows.filter(r=>existing.has(recordKey(r))).length;const subjects=[...new Set(rows.map(r=>r.subject))];const classes=[...new Set(rows.map(r=>r.year+' '+r.className))];pending={rows,version:state.version,isAdmin};const missing=rows.filter(r=>r.status!=='OK').length;const unmapped=rows.filter(r=>r.assessment==='MPT4'&&!state.records.some(x=>x.studentKey===r.studentKey&&String(x.session)===session));$('#upload-status').textContent='Selesai membaca. Sila semak sebelum meneruskan.';$('#import-preview').innerHTML=`<div class="notice"><strong>${rows.length} rekod · ${new Set(rows.map(r=>r.studentKey)).size} murid · ${classes.length} kelas</strong><p>${esc(classes.join(', '))}<br>Subjek: ${esc(subjects.join(', '))}</p><p>${updated} padanan sedia ada akan dikemas kini; ${rows.length-updated} rekod baharu. Kelas dan pentaksiran lain dikekalkan.</p></div>${rows.some(r=>r.source.includes('Belum disahkan'))?'<div class="notice warn">PDF berstatus BELUM DISAHKAN. Pastikan fail ini versi yang mahu disimpan.</div>':''}${missing?`<div class="notice warn">${missing} rekod T / TD. Status ini tidak dikira sebagai sifar.</div>`:''}${unmapped.length?`<div class="notice warn">${unmapped.length} rekod MPT4 belum mempunyai padanan data pusat. Import UASA/PBD sesi sama dahulu atau semak ID.</div>`:''}<div class="table-scroll"><table><thead><tr><th>Nama</th><th>Kelas</th><th>Subjek</th><th>Keputusan</th></tr></thead><tbody>${rows.slice(0,30).map(r=>`<tr><td>${esc(r.name)}</td><td>${r.year} ${esc(r.className)}</td><td>${esc(r.subject)}</td><td>${esc(r.tp||(r.mark??r.status))} ${esc(r.grade||'')}</td></tr>`).join('')}</tbody></table></div><p class="hint">Pratonton 30 rekod pertama. ${a.id==='MPT4'?'JUMLAH /50 ×2 → /100. Gred mengikut skala UASA.':''}</p><div class="actions"><button class="btn" id="confirm-import">${isAdmin?'Sahkan simpan ke Google Sheets':'Gunakan dalam pratonton sahaja'}</button><button class="btn secondary" id="cancel-import">Batal</button></div>`;$('#confirm-import').onclick=confirmImport;$('#cancel-import').onclick=()=>{pending=null;$('#import-preview').innerHTML='';};});};}
async function confirmImport(){if(!pending)return;const btn=$('#confirm-import');btn.disabled=true;try{if(pending.isAdmin){if(!admin)throw Error('Sesi admin diperlukan.');const d=await request('v3_import',{authToken:admin.token,records:pending.rows,expectedVersion:pending.version});pending=null;await sync(true);toast(`${d.added} rekod ditambah, ${d.updated} dikemas kini.`);go('admin');}else{if(!originalOnline)originalOnline=state;const base=state.preview?state.records:state.demo?[]:state.records;state={...state,records:mergeRows(base,pending.rows),demo:true,preview:true};f.session=String(pending.rows[0].session);f.assessment=pending.rows[0].assessment;f.assessments=[f.assessment];pending=null;initFilters();go('students');status('PRATONTON PERANTI · Belum disimpan ke Google Sheets. Admin → Sambungan untuk kembali ke data pusat.',true);}}catch(e){toast(e.message);btn.disabled=false;}}
async function changeConfig(body){try{await request('v3_config',{...body,authToken:admin.token,expectedVersion:state.version});await sync(true);go('admin');toast('Tetapan disimpan.');}catch(e){toast(e.message);}}
async function backup(){try{toast('Menyediakan sandaran…');const d=await request('v3_backup',{authToken:admin.token});download(`SAP-TEMIN-Sandaran-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(d.data,null,2),'application/json');toast('Sandaran disimpan di Drive dan dimuat turun.');}catch(e){toast(e.message);}}
async function backups(){try{const d=await request('v3_backups',{authToken:admin.token});modal('Sandaran tersedia',d.backups.map(b=>`<div class="list-item"><strong>${esc(b.kind)}</strong><p>${esc(formatDate(b.date))} · ${esc(b.note)}</p><button class="text-btn" data-restore="${esc(b.id)}">Pulihkan versi ini</button></div>`).join('')||'<p>Tiada sandaran.</p>');}catch(e){toast(e.message);}}
function confirmRestore(payload){modal('Sahkan pemulihan',`<div class="notice warn">Data dan konfigurasi v3 semasa akan diganti dengan sandaran pilihan. Sistem membuat sandaran keadaan semasa dahulu. Data PBD dan intervensi lama tidak ditulis semula.</div><form id="restore-confirm"><label>Taip PULIHKAN untuk mengesahkan<input name="confirm" required pattern="PULIHKAN"></label><div class="actions"><button class="btn danger">Pulihkan sandaran</button></div><p id="form-status" class="hint"></p></form>`);$('#restore-confirm').onsubmit=async e=>{e.preventDefault();await busy(e.target,async()=>{await request('v3_restore',{...payload,confirm:new FormData(e.target).get('confirm'),authToken:admin.token,expectedVersion:state.version});await sync(true);go('admin');toast('Pemulihan selesai.');});};}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
async function busy(form,fn){const buttons=form.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);try{await fn();}catch(e){const out=form.querySelector('#form-status,#login-status,#upload-status');if(out)out.textContent=e.message;toast(e.message);}finally{buttons.forEach(b=>b.disabled=false);}}
document.addEventListener('click',async e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.dashboardMode){dashboardMode=el.dataset.dashboardMode;homeView();}
if(el.dataset.analysisTab){analysisTab=el.dataset.analysisTab;analysisView();}
if(el.dataset.info)showInfo(el.dataset.info);
if(el.dataset.stat){const m=metrics(),kind=el.dataset.stat;let ps=[],label='Murid';if(kind==='pbd-low'){ps=m.pbdLow;label='Murid TP1 / TP2';}if(kind==='pbd-missing'){ps=people.filter(p=>!chartPbdRecords(p,f.subject).length);label='Tiada TP sah';}if(kind==='exam-low'){ps=m.markLow;label='Murid bawah '+outcomeThreshold+' markah';}if(kind==='exam-unknown'){ps=m.markUnknown;label='Markah belum lengkap';}showChartMembers(label,ps,p=>kind.startsWith('pbd')?chartPbdRecords(p,f.subject).map(r=>esc(r.subject)+' '+esc(r.tp)).join(' · '):Object.values(p.marks).filter(r=>!f.subject||r.subject===f.subject).map(r=>esc(r.subject)+' '+esc(r.status==='OK'?r.mark:r.status)).join(' · '));}
if(el.dataset.grade){const sub=el.dataset.chartSubject,g=el.dataset.grade;showChartMembers((SUBJECTS[sub]||sub)+' · Gred '+g,people.filter(p=>p.marks[sub]?.status==='OK'&&p.marks[sub]?.grade===g),p=>esc(p.marks[sub].mark)+' markah');}
if(el.dataset.go){if(el.dataset.go==='preview')preview();else go(el.dataset.go);}if(el.dataset.profile)profile(el.dataset.profile);if(el.dataset.subject){f.subject=el.dataset.subject;f.sort='subject';rebuildFilters();go('students');}if(el.dataset.tp){const tp=el.dataset.tp,sub=el.dataset.tpSubject||f.subject;showChartMembers('Murid '+tp+(sub?' · '+sub:''),tpMembers(people,tp,sub),p=>chartPbdRecords(p,sub).filter(r=>r.tp===tp).map(r=>esc(SUBJECTS[r.subject]||r.subject)+' · '+esc(r.tp)).join(' / '));}
if(el.dataset.outcome){const sub=el.dataset.chartSubject,kind=el.dataset.outcome;const label=kind==='low'?'Bawah '+outcomeThreshold+' markah':kind==='met'?outcomeThreshold+' markah ke atas':'Belum ditaksir';showChartMembers((SUBJECTS[sub]||sub)+' · '+label,outcomeMembers(people,sub,kind,outcomeThreshold),p=>{const r=p.marks[sub];return esc(r.status==='OK'?r.mark+' markah · Gred '+(r.grade||'—'):r.status||'TD');});}
if(el.dataset.work)workForm(el.dataset.work);if(el.dataset.monitor)monitorForm(el.dataset.monitor,el.dataset.kind);if(el.dataset.lock)await changeConfig({operation:'lock_session',year:el.dataset.lock,locked:el.dataset.locked==='true'});if(el.dataset.active)await changeConfig({operation:'active_session',year:el.dataset.active});if(el.dataset.restore)confirmRestore({backupId:el.dataset.restore});switch(el.dataset.action){case'report-csv':if(['pbd','marks'].includes(reportType))download(`SAP-TEMIN-${f.session}-${reportType}.csv`,summaryCsv(people,currentSubjects,reportType),'text/csv;charset=utf-8');else download(`SAP-TEMIN-${f.session}-murid.csv`,exportCsv(people,currentSubjects,f.assessment,f.sort==='subject'?'subjectRank':'rank'),'text/csv;charset=utf-8');break;case'csv':download(`SAP-TEMIN-${f.session}-${f.assessment}.csv`,exportCsv(people.filter(p=>p.name.toLowerCase().includes(search.toLowerCase())),currentSubjects,f.assessment,f.sort==='subject'?'subjectRank':'rank'),'text/csv;charset=utf-8');break;case'print':window.print();break;case'slip':printSlip();break;case'report-students':go('students');break;case'report-analysis':go('analysis');break;case'teacher':showTeacherWorkspace();break;case'teacher-out':teacher=null;sheet.close();toast('Guru telah log keluar.');break;case'admin-out':try{await request('v3_logout',{authToken:admin.token});}catch(e){}admin=null;go('home');break;case'backup':backup();break;case'backups':backups();break;case'demo':admin=null;teacher=null;state={...state,records:demoData(),demo:true,preview:false,version:''};initFilters();go('home');status('MOD CONTOH · Data rekaan sahaja.',true);break;}});
if(window.matchMedia('(max-width: 760px)').matches)$('#filters-box').open=false;
state.records=apiUrl?[]:demoData();state.demo=!apiUrl;initFilters();render();if(apiUrl){const old=await cached();if(old?.apiVersion==='3.0.0'){setData(old);status('Salinan terakhir · '+formatDate(old.version));}await sync();}else status('MOD CONTOH · Data rekaan untuk mencuba menu. Sambungan Google Sheets belum diaktifkan.',true);

function printSlip(){const content=$('#sheet-body').cloneNode(true);content.querySelectorAll('button').forEach(b=>b.remove());const out=document.createElement('section');out.id='slip-print';out.innerHTML='<h2>SK TEMIN · Slip Pencapaian Murid</h2>'+content.innerHTML;document.body.append(out);document.body.classList.add('printing-slip');const style=document.createElement('style');style.media='print';style.textContent='@page{size:A4 portrait;margin:15mm}';document.head.append(style);const cleanup=()=>{out.remove();style.remove();document.body.classList.remove('printing-slip');};window.addEventListener('afterprint',cleanup,{once:true});window.print();}
